'use strict';

const DEFAULT_METHODS = ['GET', 'HEAD', 'PUT', 'PATCH', 'POST', 'DELETE'];
const DEFAULT_OPTIONS_SUCCESS_STATUS = 204;

function isOriginAllowed(requestOrigin, allowedOrigin) {
  if (Array.isArray(allowedOrigin)) {
    return allowedOrigin.some((origin) => isOriginAllowed(requestOrigin, origin));
  }
  if (allowedOrigin instanceof RegExp) {
    return allowedOrigin.test(requestOrigin);
  }
  if (typeof allowedOrigin === 'function') {
    return !!allowedOrigin(requestOrigin);
  }
  if (allowedOrigin === true) {
    return true;
  }
  if (allowedOrigin === false || allowedOrigin == null) {
    return false;
  }
  return String(allowedOrigin) === requestOrigin;
}

function configureOrigin(options, req) {
  const requestOrigin = req.headers && req.headers.origin ? String(req.headers.origin) : undefined;
  const { origin } = options;

  if (origin == null) {
    return requestOrigin || '*';
  }
  if (origin === '*') {
    return '*';
  }
  if (origin === true) {
    return requestOrigin || '*';
  }
  if (origin === false) {
    return false;
  }
  if (typeof origin === 'function') {
    return origin(requestOrigin, req);
  }
  if (Array.isArray(origin)) {
    if (!requestOrigin) return false;
    if (origin.includes('*')) return '*';
    return origin.find((allowed) => isOriginAllowed(requestOrigin, allowed)) || false;
  }
  if (origin instanceof RegExp) {
    if (!requestOrigin) return false;
    return origin.test(requestOrigin) ? requestOrigin : false;
  }
  return String(origin);
}

function appendHeader(res, header, value) {
  const current = res.getHeader && res.getHeader(header);
  if (!current) {
    res.setHeader(header, value);
    return;
  }
  const headerValue = Array.isArray(current) ? current.join(',') : String(current);
  if (!headerValue.split(/,\s*/).includes(value)) {
    res.setHeader(header, `${headerValue}, ${value}`);
  }
}

function configureMethods(options) {
  const methods = options.methods || DEFAULT_METHODS;
  if (Array.isArray(methods)) {
    return methods.map((method) => method.toUpperCase()).join(',');
  }
  return String(methods).split(',').map((method) => method.trim().toUpperCase()).join(',');
}

function configureAllowedHeaders(options, req) {
  const headers = options.allowedHeaders || req.headers['access-control-request-headers'];
  if (!headers) return undefined;
  if (Array.isArray(headers)) {
    return headers.join(',');
  }
  return String(headers);
}

function configureExposedHeaders(options) {
  const headers = options.exposedHeaders;
  if (!headers) return undefined;
  if (Array.isArray(headers)) {
    return headers.join(',');
  }
  return String(headers);
}

function configureMaxAge(options) {
  if (options.maxAge == null) return undefined;
  const value = typeof options.maxAge === 'number' ? options.maxAge : parseInt(options.maxAge, 10);
  if (Number.isNaN(value)) return undefined;
  return String(value);
}

function createCorsMiddleware(userOptions) {
  const options = userOptions || {};

  return function corsMiddleware(req, res, next) {
    const requestOrigin = req.headers && req.headers.origin ? String(req.headers.origin) : undefined;
    const origin = configureOrigin(options, req);

    if (origin === false) {
      return next();
    }

    if (origin && res.setHeader) {
      res.setHeader('Access-Control-Allow-Origin', origin === true ? requestOrigin || '*' : origin);
      if (origin !== '*' && requestOrigin) {
        appendHeader(res, 'Vary', 'Origin');
      }
    }

    if (options.credentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    const exposedHeaders = configureExposedHeaders(options);
    if (exposedHeaders) {
      res.setHeader('Access-Control-Expose-Headers', exposedHeaders);
    }

    if (req.method && req.method.toUpperCase() === 'OPTIONS') {
      // Preflight
      const allowMethods = configureMethods(options);
      res.setHeader('Access-Control-Allow-Methods', allowMethods);

      const allowedHeaders = configureAllowedHeaders(options, req);
      if (allowedHeaders) {
        res.setHeader('Access-Control-Allow-Headers', allowedHeaders);
        appendHeader(res, 'Vary', 'Access-Control-Request-Headers');
      }

      const maxAge = configureMaxAge(options);
      if (maxAge) {
        res.setHeader('Access-Control-Max-Age', maxAge);
      }

      const status = options.optionsSuccessStatus || DEFAULT_OPTIONS_SUCCESS_STATUS;
      res.statusCode = status;
      res.setHeader('Content-Length', '0');
      res.end();
      return;
    }

    return next();
  };
}

function cors(options) {
  const middleware = createCorsMiddleware(options);
  return middleware;
}

module.exports = cors;
module.exports.default = cors;
module.exports.configureOrigin = configureOrigin;
module.exports._private = {
  configureAllowedHeaders,
  configureExposedHeaders,
  configureMaxAge,
  configureMethods
};
